-- OBE governance: batch set-up progress, OMC review of a batch (proposals, PL opinions, endorsements), SE plan approval
-- (votes, SE <-> OMC thread, final state), assessment-limit consultation rounds, 2-member request votes and 3-member
-- panels, GA crosswalks between programs, other departments' courses mapped to our GAs per term, and courses planned
-- for a program by another department. Safe to run more than once.
CREATE TABLE IF NOT EXISTS "BatchSetupStep" ("batchId" TEXT NOT NULL, "step" TEXT NOT NULL, "byId" TEXT NOT NULL, "byName" TEXT NOT NULL DEFAULT '', "at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("batchId", "step"));
CREATE TABLE IF NOT EXISTS "BatchReview" ("batchId" TEXT PRIMARY KEY, "status" TEXT NOT NULL DEFAULT 'SUBMITTED', "submittedById" TEXT NOT NULL, "submittedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "decidedById" TEXT, "decidedByName" TEXT, "decidedAt" TIMESTAMP(3), "summary" TEXT);
CREATE TABLE IF NOT EXISTS "BatchReviewProposal" ("id" TEXT PRIMARY KEY, "batchId" TEXT NOT NULL, "courseId" TEXT, "kind" TEXT NOT NULL, "payload" TEXT NOT NULL DEFAULT '{}', "text" TEXT NOT NULL, "reason" TEXT, "byId" TEXT NOT NULL, "byName" TEXT NOT NULL DEFAULT '', "at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "status" TEXT NOT NULL DEFAULT 'PROPOSED', "plOpinion" TEXT, "plComment" TEXT, "plAt" TIMESTAMP(3));
CREATE INDEX IF NOT EXISTS "BatchReviewProposal_batchId_idx" ON "BatchReviewProposal"("batchId");
CREATE TABLE IF NOT EXISTS "BatchReviewEndorse" ("batchId" TEXT NOT NULL, "userId" TEXT NOT NULL, "userName" TEXT NOT NULL DEFAULT '', "endorse" BOOLEAN NOT NULL, "comment" TEXT, "at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("batchId", "userId"));
CREATE TABLE IF NOT EXISTS "PlanState" ("courseId" TEXT PRIMARY KEY, "round" INTEGER NOT NULL DEFAULT 1, "status" TEXT NOT NULL DEFAULT 'SUBMITTED', "recheckedAt" TIMESTAMP(3), "omcFinal" BOOLEAN NOT NULL DEFAULT FALSE, "finalNote" TEXT, "decidedById" TEXT, "at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "PlanVote" ("courseId" TEXT NOT NULL, "round" INTEGER NOT NULL, "userId" TEXT NOT NULL, "userName" TEXT NOT NULL DEFAULT '', "approve" BOOLEAN NOT NULL, "comment" TEXT, "at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("courseId", "round", "userId"));
CREATE TABLE IF NOT EXISTS "PlanThread" ("id" TEXT PRIMARY KEY, "courseId" TEXT NOT NULL, "round" INTEGER NOT NULL DEFAULT 1, "parentId" TEXT, "byId" TEXT NOT NULL, "byName" TEXT NOT NULL DEFAULT '', "side" TEXT NOT NULL, "kind" TEXT NOT NULL, "step" TEXT, "text" TEXT NOT NULL, "at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "PlanThread_courseId_idx" ON "PlanThread"("courseId");
CREATE TABLE IF NOT EXISTS "RuleRound" ("id" TEXT PRIMARY KEY, "chairmanId" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'OPEN', "openedById" TEXT NOT NULL, "openedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "lockedById" TEXT, "lockedAt" TIMESTAMP(3), "decision" TEXT);
CREATE INDEX IF NOT EXISTS "RuleRound_chairmanId_idx" ON "RuleRound"("chairmanId");
CREATE TABLE IF NOT EXISTS "RuleOpinion" ("roundId" TEXT NOT NULL, "userId" TEXT NOT NULL, "userName" TEXT NOT NULL DEFAULT '', "category" TEXT NOT NULL, "figures" TEXT NOT NULL DEFAULT '{}', "comment" TEXT, "at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("roundId", "userId", "category"));
CREATE TABLE IF NOT EXISTS "RequestVote" ("kind" TEXT NOT NULL, "requestId" TEXT NOT NULL, "userId" TEXT NOT NULL, "userName" TEXT NOT NULL DEFAULT '', "approve" BOOLEAN NOT NULL, "reason" TEXT, "at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("kind", "requestId", "userId"));
CREATE TABLE IF NOT EXISTS "OmcPanel" ("courseId" TEXT PRIMARY KEY, "memberIds" TEXT NOT NULL DEFAULT '[]', "byId" TEXT NOT NULL, "at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "GaCrosswalk" ("id" TEXT PRIMARY KEY, "chairmanId" TEXT NOT NULL, "ourProgram" TEXT NOT NULL, "theirProgram" TEXT NOT NULL, "map" TEXT NOT NULL DEFAULT '[]', "status" TEXT NOT NULL DEFAULT 'DRAFT', "byId" TEXT NOT NULL, "at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "history" TEXT NOT NULL DEFAULT '[]');
CREATE UNIQUE INDEX IF NOT EXISTS "GaCrosswalk_pair_key" ON "GaCrosswalk"("chairmanId", "ourProgram", "theirProgram");
CREATE TABLE IF NOT EXISTS "GaCrosswalkEndorse" ("crosswalkId" TEXT NOT NULL, "userId" TEXT NOT NULL, "userName" TEXT NOT NULL DEFAULT '', "endorse" BOOLEAN NOT NULL, "comment" TEXT, "at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("crosswalkId", "userId"));
CREATE TABLE IF NOT EXISTS "ForeignCourseGa" ("courseId" TEXT NOT NULL, "term" TEXT NOT NULL, "gas" TEXT NOT NULL DEFAULT '[]', "confirmedBy" TEXT NOT NULL DEFAULT '[]', "status" TEXT NOT NULL DEFAULT 'PENDING', "at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("courseId", "term"));
CREATE TABLE IF NOT EXISTS "CourseHomePlan" ("courseId" TEXT PRIMARY KEY, "mode" TEXT NOT NULL, "linkedCourseId" TEXT, "byId" TEXT NOT NULL, "at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
